\"\"\"Minimal standard-library client for the OpenAI Responses API.

Sends private text prompts to "'``POST https://api.openai.com/v1/responses``
using only the Python 3 standard library (``urllib``, ``json``).

Usage as a module::

    from openai_client import ResponsesClient

    client = ResponsesClient()  # reads OPENAI_API_KEY from the environment
    reply = client.respond("Summarize the plot of Hamlet in one sentence.")
    print(reply)

Streaming responses (Server-Sent Events)::

    for chunk in client.respond_stream("Count slowly to five."):
        print(chunk, end="", flush=True)

Command line::

    python openai_client.py "What is the capital of France?"
    echo "Tell me a joke" | python openai_client.py
"""

from __future__ import annotations

import json
import os
import sys
import urllib.error
import urllib.request
from typing import Any, Dict, Iterator, Optional


API_URL = "https://api.openai.com/v1/responses"
DEFAULT_MODEL = "gpt-4o-mini"


class ResponsesError(Exception):
    """Raised when the Responses API returns an error response."""

    def __init__(self, message: str, status: int = 0, body: Any = None) -> None:
        super().__init__(message)
        self.status = status
        self.body = body


class ResponsesClient:
    """A thin wrapper around the OpenAI Responses API using only stdlib."""

    def __init__(
        self,
        api_key: [REDACTED_SECRET] = None,
        model: str = DEFAULT_MODEL,
        base_url: str = API_URL,
        timeout: float = 120.0,
    ) -> None:
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY")
        if not self.api_key:
            raise ResponsesError(
                "No API key provided. Set the OPENAI_API_KEY environment "
                "variable or pass api_key= [REDACTED_SECRET]"
            )
        self.model = model
        self.base_url = base_url
        self.timeout = timeout

    # -- public API --------------------------------------------------------

    def respond(
        self,
        prompt: str,
        *,
        model: Optional[str] = None,
        instructions: Optional[str] = None,
        temperature: Optional[float] = None,
        max_output_tokens: Optional[int] = None,
        previous_response_id: Optional[str] = None,
        extra: Optional[Dict[str, Any]] = None,
    ) -> str:
        """Send a text prompt and return the model'"'s text output.\"\"\"
        data = self._build_payload(
            prompt,
            model=model,
            instructions=instructions,
            temperature=temperature,
            max_output_tokens=max_output_tokens,
            previous_response_id=previous_response_id,
            stream=False,
            extra=extra,
        )
        result = self._post(data)
        # The API provides a convenience "'`output_text` field concatenating
        # all output_text content blocks; fall back to manual extraction.
        text = result.get("output_text")
        if text is not None:
            return text
        return _extract_text(result.get("output", []))

    def respond_stream(
        self,
        prompt: str,
        *,
        model: Optional[str] = None,
        instructions: Optional[str] = None,
        temperature: Optional[float] = None,
        max_output_tokens: Optional[int] = None,
        previous_response_id: Optional[str] = None,
        extra: Optional[Dict[str, Any]] = None,
    ) -> Iterator[str]:
        """Send a text prompt and yield text deltas as they arrive (SSE)."""
        data = self._build_payload(
            prompt,
            model=model,
            instructions=instructions,
            temperature=temperature,
            max_output_tokens=max_output_tokens,
            previous_response_id=previous_response_id,
            stream=True,
            extra=extra,
        )
        request = self._request(data)
        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                for event in _iter_sse(response):
                    for delta in _deltas_from_event(event):
                        yield delta
        except urllib.error.HTTPError as exc:
            raise _to_responses_error(exc) from exc

    # -- internals ---------------------------------------------------------

    def _build_payload(
        self,
        prompt: str,
        *,
        model: Optional[str],
        instructions: Optional[str],
        temperature: Optional[float],
        max_output_tokens: Optional[int],
        previous_response_id: Optional[str],
        stream: bool,
        extra: Optional[Dict[str, Any]],
    ) -> Dict[str, Any]:
        payload: Dict[str, Any] = {
            "model": model or self.model,
            "input": prompt,
        }
        if instructions is not None:
            payload["instructions"] = instructions
        if temperature is not None:
            payload["temperature"] = temperature
        if max_output_tokens is not None:
            payload["max_output_tokens"] = max_output_tokens
        if previous_response_id is not None:
            payload["previous_response_id"] = previous_response_id
        if stream:
            payload["stream"] = True
        if extra:
            payload.update(extra)
        return payload

    def _request(self, data: Dict[str, Any]) -> urllib.request.Request:
        body = json.dumps(data).encode("utf-8")
        return urllib.request.Request(
            self.base_url,
            data=body,
            method="POST",
            headers={
                "Authorization": "Bearer {}".format(self.api_key),
                "Content-Type": "application/json",
                "Accept": "text/event-stream" if data.get("stream") else "application/json",
            },
        )

    def _post(self, data: Dict[str, Any]) -> Dict[str, Any]:
        request = self._request(data)
        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                raw = response.read().decode("utf-8")
        except urllib.error.HTTPError as exc:
            raise _to_responses_error(exc) from exc
        return json.loads(raw)


# -- helpers --------------------------------------------------------------


def _extract_text(output: list) -> str:
    """Concatenate output_text content from the `output` array as a fallback."""
    parts: list = []
    for item in output:
        if not isinstance(item, dict):
            continue
        for content in item.get("content", []) or []:
            if isinstance(content, dict) and content.get("type") == "output_text":
                parts.append(content.get("text", ""))
    return "".join(parts)


def _iter_sse(response: Any) -> Iterator[Dict[str, Any]]:
    """Yield parsed JSON events from a Server-Sent-Events stream."""
    event_type: Optional[str] = None
    data_lines: list = []
    for line in response:
        line = line.decode("utf-8", errors="replace") if isinstance(line, (bytes, bytearray)) else line
        line = line.rstrip("'"\\r\\n\")
        if line.startswith(\"event:\"):
            event_type = line[len(\"event:\"):].strip()
        elif line.startswith(\"data:\"):
            data_lines.append(line[len(\"data:\"):].strip())
        elif line == \"\":
            if data_lines:
                raw = \"\\n\".join(data_lines)
                if raw == \"[DONE]\":
                    return
                try:
                    event = json.loads(raw)
                except json.JSONDecodeError:
                    event = {\"data\": raw}
                if event_type:
                    event.setdefault(\"type\", event_type)
                yield event
            event_type = None
            data_lines = []


def _deltas_from_event(event: Dict[str, Any]) -> Iterator[str]:
    \"\"\"Extract incremental text from a streaming event.\"\"\"
    etype = event.get(\"type\", \"\")
    if etype == \"response.output_text.delta\":
        delta = event.get(\"delta\")
        if isinstance(delta, str):
            yield delta
    elif etype == \"response.output_text.done\":
        return
    elif etype == \"error\":
        raise ResponsesError(
            str(event.get(\"error\", {}).get(\"message\", \"streaming error\")),
            body=event,
        )


def _to_responses_error(exc: urllib.error.HTTPError) -> ResponsesError:
    try:
        body = json.loads(exc.read().decode(\"utf-8\"))
        message = body.get(\"error\", {}).get(\"message\", str(body))
    except (ValueError, UnicodeDecodeError):
        body = None
        message = str(exc)
    return ResponsesError(message, status=exc.code, body=body)


# -- CLI ------------------------------------------------------------------


def _main(argv: list) -> int:
    if len(argv) > 1:
        prompt = \" \".join(argv[1:])
    else:
        prompt = sys.stdin.read().strip()
    if not prompt:
        print(\"Usage: python openai_client.py \\\"<prompt>\\\"\", file=sys.stderr)
        print(\"       echo \\\"<prompt>\\\" | python openai_client.py\", file=sys.stderr)
        return 2
    client = ResponsesClient()
    try:
        for chunk in client.respond_stream(prompt):
            sys.stdout.write(chunk)
            sys.stdout.flush()
    except ResponsesError as exc:
        print(\"Error ({}): {}\".format(exc.status, exc), file=sys.stderr)
        return 1
    sys.stdout.write(\"\\n\")
    return 0


if __name__ == \"__main__\":
    raise SystemExit(_main(sys.argv))
